use super::*;

const IC_INTR_BITS: u32 = 0x1fff;
// RP2350's mask register uses one bits to *unmask* sources.  The reset value
// is the value generated by the official Pico SDK register description: the
// general-call and low-level FIFO/status sources start unmasked, while the
// start/stop/activity/restart sources start masked.
const IC_INTR_MASK_RESET: u32 = 0x08ff;
const IC_CON_WRITABLE_BITS: u32 = 0x03ff;
const IC_FIFO_DEPTH: usize = 16;

/// RP2350 DW_apb_i2c register identifiers shared by I2C0 and I2C1.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[repr(u16)]
pub enum RpI2cRegister {
    /// I²C control register.
    Control = 0x00,
    /// Target address register.
    TargetAddress = 0x04,
    /// Slave address register.
    SlaveAddress = 0x08,
    /// Combined transmit/receive command register.
    DataCommand = 0x10,
    /// Standard-speed SCL high-count register.
    StandardSpeedHighCount = 0x14,
    /// Standard-speed SCL low-count register.
    StandardSpeedLowCount = 0x18,
    /// Fast-mode SCL high-count register.
    FastSpeedHighCount = 0x1c,
    /// Fast-mode SCL low-count register.
    FastSpeedLowCount = 0x20,
    /// Masked interrupt status register.
    InterruptStatus = 0x2c,
    /// Interrupt mask register; one bits unmask their corresponding source.
    InterruptMask = 0x30,
    /// Raw interrupt status register.
    RawInterruptStatus = 0x34,
    /// Receive FIFO threshold register.
    ReceiveThreshold = 0x38,
    /// Transmit FIFO threshold register.
    TransmitThreshold = 0x3c,
    /// Read-clear aggregate interrupt register.
    ClearInterrupt = 0x40,
    /// Read-clear receive-underflow register.
    ClearReceiveUnderflow = 0x44,
    /// Read-clear receive-overflow register.
    ClearReceiveOverflow = 0x48,
    /// Read-clear transmit-overflow register.
    ClearTransmitOverflow = 0x4c,
    /// Read-clear read-request register.
    ClearReadRequest = 0x50,
    /// Read-clear transmit-abort register.
    ClearTransmitAbort = 0x54,
    /// Read-clear receive-done register.
    ClearReceiveDone = 0x58,
    /// Read-clear activity register.
    ClearActivity = 0x5c,
    /// Read-clear stop-detect register.
    ClearStopDetected = 0x60,
    /// Read-clear start-detect register.
    ClearStartDetected = 0x64,
    /// Read-clear general-call register.
    ClearGeneralCall = 0x68,
    /// Enable and abort control register.
    Enable = 0x6c,
    /// Read-only controller status register.
    Status = 0x70,
    /// Transmit FIFO level register.
    TransmitFifoLevel = 0x74,
    /// Receive FIFO level register.
    ReceiveFifoLevel = 0x78,
    /// SDA hold-time register.
    SdaHold = 0x7c,
    /// Transmit-abort source register.
    TransmitAbortSource = 0x80,
    /// Slave data NACK-only control register.
    SlaveDataNackOnly = 0x84,
    /// DMA control register.
    DmaControl = 0x88,
    /// DMA transmit watermark register.
    DmaTransmitLevel = 0x8c,
    /// DMA receive watermark register.
    DmaReceiveLevel = 0x90,
    /// SDA setup-time register.
    SdaSetup = 0x94,
    /// General-call ACK control register.
    AckGeneralCall = 0x98,
    /// Read-only enable status register.
    EnableStatus = 0x9c,
    /// Fast-mode spike suppression register.
    FastSpeedSpikeLength = 0xa0,
    /// Read-clear restart-detect register.
    ClearRestartDetected = 0xa8,
    /// DesignWare component parameter register (not implemented in silicon).
    ComponentParameter = 0xf4,
    /// DesignWare component version register.
    ComponentVersion = 0xf8,
    /// DesignWare component type register.
    ComponentType = 0xfc,
}

impl RpI2cRegister {
    /// Converts a native register offset to a typed identifier.
    pub const fn from_offset(offset: u64) -> Option<Self> {
        Some(match offset {
            0x00 => Self::Control,
            0x04 => Self::TargetAddress,
            0x08 => Self::SlaveAddress,
            0x10 => Self::DataCommand,
            0x14 => Self::StandardSpeedHighCount,
            0x18 => Self::StandardSpeedLowCount,
            0x1c => Self::FastSpeedHighCount,
            0x20 => Self::FastSpeedLowCount,
            0x2c => Self::InterruptStatus,
            0x30 => Self::InterruptMask,
            0x34 => Self::RawInterruptStatus,
            0x38 => Self::ReceiveThreshold,
            0x3c => Self::TransmitThreshold,
            0x40 => Self::ClearInterrupt,
            0x44 => Self::ClearReceiveUnderflow,
            0x48 => Self::ClearReceiveOverflow,
            0x4c => Self::ClearTransmitOverflow,
            0x50 => Self::ClearReadRequest,
            0x54 => Self::ClearTransmitAbort,
            0x58 => Self::ClearReceiveDone,
            0x5c => Self::ClearActivity,
            0x60 => Self::ClearStopDetected,
            0x64 => Self::ClearStartDetected,
            0x68 => Self::ClearGeneralCall,
            0x6c => Self::Enable,
            0x70 => Self::Status,
            0x74 => Self::TransmitFifoLevel,
            0x78 => Self::ReceiveFifoLevel,
            0x7c => Self::SdaHold,
            0x80 => Self::TransmitAbortSource,
            0x84 => Self::SlaveDataNackOnly,
            0x88 => Self::DmaControl,
            0x8c => Self::DmaTransmitLevel,
            0x90 => Self::DmaReceiveLevel,
            0x94 => Self::SdaSetup,
            0x98 => Self::AckGeneralCall,
            0x9c => Self::EnableStatus,
            0xa0 => Self::FastSpeedSpikeLength,
            0xa8 => Self::ClearRestartDetected,
            0xf4 => Self::ComponentParameter,
            0xf8 => Self::ComponentVersion,
            0xfc => Self::ComponentType,
            _ => return None,
        })
    }

    /// Returns the native byte offset represented by this identifier.
    pub const fn offset(self) -> u64 {
        self as u64
    }
}

/// deterministic while making the byte stream visible to VCD consumers.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum RpI2cEvent {
    /// A transaction started while the controller was idle.
    Start,
    /// A repeated-start command was issued during an active transaction.
    RepeatedStart,
    /// A byte was written to the selected seven-bit target.
    Write {
        /// Seven-bit target address (or the low ten bits when configured).
        address: u16,
        /// Data byte written to the target.
        value: u8,
    },
    /// A byte was returned to the controller's receive FIFO.
    Read {
        /// Seven-bit target address (or the low ten bits when configured).
        address: u16,
        /// Data byte returned by the deterministic host target.
        value: u8,
    },
    /// The command stream requested a STOP condition.
    Stop,
}

struct RpI2cState {
    con: u32,
    tar: u32,
    sar: u32,
    ss_scl_hcnt: u32,
    ss_scl_lcnt: u32,
    fs_scl_hcnt: u32,
    fs_scl_lcnt: u32,
    intr_mask: u32,
    rx_tl: u32,
    tx_tl: u32,
    sda_hold: u32,
    tx_abrt_source: u32,
    slave_data_nack_only: bool,
    dma_control: u32,
    dma_tx_level: u32,
    dma_rx_level: u32,
    sda_setup: u32,
    ack_general_call: bool,
    fs_spklen: u32,
    enable: bool,
    tx_cmd_block: bool,
    raw_intr: u32,
    tx_fifo: VecDeque<u32>,
    rx_fifo: VecDeque<u8>,
    queued_reads: BTreeMap<u16, VecDeque<u8>>,
    events: Vec<RpI2cEvent>,
    active: bool,
    byte_signal: SignalId,
    strobe_signal: SignalId,
    strobe: bool,
}

impl RpI2cState {
    fn new(byte_signal: SignalId, strobe_signal: SignalId) -> Self {
        Self {
            con: 0x65,
            tar: 0x55,
            sar: 0x55,
            ss_scl_hcnt: 0x28,
            ss_scl_lcnt: 0x2f,
            fs_scl_hcnt: 0x06,
            fs_scl_lcnt: 0x0d,
            intr_mask: IC_INTR_MASK_RESET,
            rx_tl: 0,
            tx_tl: 0,
            sda_hold: 0x01,
            tx_abrt_source: 0,
            slave_data_nack_only: false,
            dma_control: 0,
            dma_tx_level: 0,
            dma_rx_level: 0,
            sda_setup: 0x64,
            ack_general_call: true,
            fs_spklen: 0x07,
            enable: false,
            tx_cmd_block: false,
            raw_intr: 0,
            tx_fifo: VecDeque::new(),
            rx_fifo: VecDeque::new(),
            queued_reads: BTreeMap::new(),
            events: Vec::new(),
            active: false,
            byte_signal,
            strobe_signal,
            strobe: false,
        }
    }

    fn reset(&mut self) {
        self.con = 0x65;
        self.tar = 0x55;
        self.sar = 0x55;
        self.ss_scl_hcnt = 0x28;
        self.ss_scl_lcnt = 0x2f;
        self.fs_scl_hcnt = 0x06;
        self.fs_scl_lcnt = 0x0d;
        self.intr_mask = IC_INTR_MASK_RESET;
        self.rx_tl = 0;
        self.tx_tl = 0;
        self.sda_hold = 0x01;
        self.tx_abrt_source = 0;
        self.slave_data_nack_only = false;
        self.dma_control = 0;
        self.dma_tx_level = 0;
        self.dma_rx_level = 0;
        self.sda_setup = 0x64;
        self.ack_general_call = true;
        self.fs_spklen = 0x07;
        self.enable = false;
        self.tx_cmd_block = false;
        self.raw_intr = 0;
        self.tx_fifo.clear();
        self.rx_fifo.clear();
        self.queued_reads.clear();
        self.events.clear();
        self.active = false;
        self.strobe = false;
    }

    fn pending(&self) -> bool {
        self.raw_intr & self.intr_mask != 0
    }
}

/// Scheduler and test-facing view of an RP2350 I²C controller.
#[derive(Clone)]
pub struct RpI2cHandle {
    state: Rc<RefCell<RpI2cState>>,
}

impl RpI2cHandle {
    /// Queues bytes returned by a deterministic host-side seven-bit target.
    pub fn queue_read(&self, address: u16, bytes: impl IntoIterator<Item = u8>) {
        self.state
            .borrow_mut()
            .queued_reads
            .entry(address & 0x03ff)
            .or_default()
            .extend(bytes);
    }

    /// Returns the logical transactions observed since reset or the last clear.
    pub fn events(&self) -> Vec<RpI2cEvent> {
        self.state.borrow().events.clone()
    }

    /// Clears the transaction history without disturbing controller state.
    pub fn clear_events(&self) {
        self.state.borrow_mut().events.clear();
    }

    /// Returns whether an enabled I²C interrupt is pending.
    pub fn pending(&self) -> bool {
        self.state.borrow().pending()
    }
}

/// Functional RP2350 I²C0/I²C1 host controller.
///
/// This models the RP2350's Synopsys DW_apb_i2c register contract closely
/// enough for SDK initialization and bounded firmware tests: controller
/// configuration, target selection, DATA_CMD read/write/STOP commands, RX
/// FIFO status, interrupt latches, and deterministic host responses.  It does
/// not yet model pin-level arbitration, slave mode, DMA, or clock-accurate
/// SCL/SDA timing. Register reset values and access restrictions are audited
/// against the [RP2350 datasheet](https://datasheets.raspberrypi.com/rp2350/rp2350-datasheet.pdf)
/// and Raspberry Pi's generated `hardware/regs/i2c.h` definitions.
pub struct RpI2c {
    name: String,
    state: Rc<RefCell<RpI2cState>>,
    hub: SignalHub,
}

impl RpI2c {
    const IC_DATA_CMD_READ: u32 = 1 << 8;
    const IC_DATA_CMD_STOP: u32 = 1 << 9;
    const IC_DATA_CMD_RESTART: u32 = 1 << 10;
    const IC_INTR_RX_UNDER: u32 = 1 << 0;
    const IC_INTR_RX_OVER: u32 = 1 << 1;
    const IC_INTR_RX_FULL: u32 = 1 << 2;
    const IC_INTR_TX_OVER: u32 = 1 << 3;
    const IC_INTR_TX_EMPTY: u32 = 1 << 4;
    const IC_INTR_RD_REQ: u32 = 1 << 5;
    const IC_INTR_TX_ABRT: u32 = 1 << 6;
    const IC_INTR_RX_DONE: u32 = 1 << 7;
    const IC_INTR_ACTIVITY: u32 = 1 << 8;
    const IC_INTR_STOP_DET: u32 = 1 << 9;
    const IC_INTR_START_DET: u32 = 1 << 10;
    const IC_INTR_GEN_CALL: u32 = 1 << 11;
    const IC_INTR_RESTART_DET: u32 = 1 << 12;
    const IC_INTR_HARDWARE_CLEARABLE: u32 = Self::IC_INTR_TX_EMPTY | Self::IC_INTR_RX_FULL;
    const IC_INTR_SOFTWARE_CLEARABLE: u32 = IC_INTR_BITS & !Self::IC_INTR_HARDWARE_CLEARABLE;

    fn atomic_write(alias: u64, current: u32, value: u32) -> u32 {
        match alias {
            0 => value,
            1 => current ^ value,
            2 => current | value,
            3 => current & !value,
            _ => unreachable!("RP2350 I²C atomic alias is two bits"),
        }
    }

    fn update_fifo_interrupts(state: &mut RpI2cState) {
        let rx_threshold = usize::try_from(state.rx_tl).unwrap_or(IC_FIFO_DEPTH - 1) + 1;
        if state.enable && state.rx_fifo.len() >= rx_threshold {
            state.raw_intr |= Self::IC_INTR_RX_FULL;
        } else {
            state.raw_intr &= !Self::IC_INTR_RX_FULL;
        }
        let tx_level = state.tx_fifo.len();
        if state.enable && tx_level <= usize::try_from(state.tx_tl).unwrap_or(IC_FIFO_DEPTH - 1) {
            state.raw_intr |= Self::IC_INTR_TX_EMPTY;
        } else {
            state.raw_intr &= !Self::IC_INTR_TX_EMPTY;
        }
    }

    fn clear_combined_interrupts(state: &mut RpI2cState) {
        state.raw_intr &= !Self::IC_INTR_SOFTWARE_CLEARABLE;
        state.tx_abrt_source = 0;
        Self::update_fifo_interrupts(state);
    }

    fn clear_abort(state: &mut RpI2cState) {
        state.raw_intr &= !Self::IC_INTR_TX_ABRT;
        state.tx_abrt_source = 0;
    }

    fn flush_fifos(state: &mut RpI2cState) {
        state.tx_fifo.clear();
        state.rx_fifo.clear();
        state.raw_intr &= !(Self::IC_INTR_RX_FULL | Self::IC_INTR_TX_EMPTY);
    }
    /// Creates a reset controller and scheduler-facing handle.
    pub fn new(
        name: impl Into<String>,
        signal_path: &str,
        hub: SignalHub,
    ) -> Result<(Self, RpI2cHandle), SignalError> {
        let byte_signal = hub.declare(
            format!("{signal_path}.byte"),
            SignalValue::from_u64(0, 8)?,
            Some("Functional I²C transaction byte".to_owned()),
        )?;
        let strobe_signal = hub.declare(
            format!("{signal_path}.strobe"),
            SignalValue::from_u64(0, 1)?,
            Some("I²C transaction strobe".to_owned()),
        )?;
        let state = Rc::new(RefCell::new(RpI2cState::new(byte_signal, strobe_signal)));
        Ok((
            Self {
                name: name.into(),
                state: state.clone(),
                hub,
            },
            RpI2cHandle { state },
        ))
    }

    fn publish_byte(
        &self,
        state: &mut RpI2cState,
        value: u8,
        at: SimTime,
    ) -> Result<(), DeviceError> {
        state.strobe = !state.strobe;
        self.hub
            .set(
                state.byte_signal,
                SignalValue::from_u64(u64::from(value), 8)
                    .map_err(|error| DeviceError::new(error.to_string()))?,
                at,
            )
            .map_err(|error| DeviceError::new(error.to_string()))?;
        self.hub
            .set(
                state.strobe_signal,
                SignalValue::from_u64(u64::from(state.strobe), 1)
                    .map_err(|error| DeviceError::new(error.to_string()))?,
                at,
            )
            .map_err(|error| DeviceError::new(error.to_string()))
    }

    fn clear_interrupt(state: &mut RpI2cState, mask: u32) {
        state.raw_intr &= !mask;
    }

    fn read_clear_value(state: &mut RpI2cState, mask: u32) -> u32 {
        let value = u32::from(state.raw_intr & mask != 0);
        Self::clear_interrupt(state, mask);
        value
    }

    fn complete_command(
        &self,
        state: &mut RpI2cState,
        command: u32,
        at: SimTime,
    ) -> Result<(), DeviceError> {
        let address = (state.tar & 0x03ff) as u16;
        if !state.active {
            state.active = true;
            state.events.push(RpI2cEvent::Start);
            state.raw_intr |= Self::IC_INTR_START_DET | Self::IC_INTR_ACTIVITY;
        } else if command & Self::IC_DATA_CMD_RESTART != 0 {
            state.events.push(RpI2cEvent::RepeatedStart);
            state.raw_intr |= Self::IC_INTR_RESTART_DET | Self::IC_INTR_ACTIVITY;
        }
        let value = (command & 0xff) as u8;
        if command & Self::IC_DATA_CMD_READ != 0 {
            let value = state
                .queued_reads
                .get_mut(&address)
                .and_then(VecDeque::pop_front)
                .unwrap_or(0xff);
            if state.rx_fifo.len() >= IC_FIFO_DEPTH {
                if state.con & (1 << 9) == 0 {
                    state.raw_intr |= Self::IC_INTR_RX_OVER;
                }
            } else {
                state.rx_fifo.push_back(value);
                state.events.push(RpI2cEvent::Read { address, value });
                state.raw_intr |= Self::IC_INTR_RX_DONE;
            }
            self.publish_byte(state, value, at)?;
        } else {
            state.events.push(RpI2cEvent::Write { address, value });
            self.publish_byte(state, value, at)?;
        }
        if command & Self::IC_DATA_CMD_STOP != 0 {
            state.active = false;
            state.events.push(RpI2cEvent::Stop);
            state.raw_intr |= Self::IC_INTR_STOP_DET;
        }
        Self::update_fifo_interrupts(state);
        Ok(())
    }

    fn drain_tx_fifo(&self, state: &mut RpI2cState, at: SimTime) -> Result<(), DeviceError> {
        while !state.tx_cmd_block {
            let Some(command) = state.tx_fifo.pop_front() else {
                break;
            };
            self.complete_command(state, command, at)?;
        }
        Self::update_fifo_interrupts(state);
        Ok(())
    }
}

impl Device for RpI2c {
    fn name(&self) -> &str {
        &self.name
    }

    fn read(&mut self, offset: u64, width: AccessWidth, _at: SimTime) -> Result<u64, DeviceError> {
        if width == AccessWidth::DoubleWord {
            return Err(DeviceError::new(
                "RP2350 I²C does not support 64-bit access",
            ));
        }
        let register_offset = (offset & 0x0fff) & !3;
        let lane = offset & 3;
        let register = RpI2cRegister::from_offset(register_offset);
        let mut state = self.state.borrow_mut();
        let value = match register {
            Some(RpI2cRegister::Control) => state.con,
            Some(RpI2cRegister::TargetAddress) => state.tar,
            Some(RpI2cRegister::SlaveAddress) => state.sar,
            Some(RpI2cRegister::StandardSpeedHighCount) => state.ss_scl_hcnt,
            Some(RpI2cRegister::StandardSpeedLowCount) => state.ss_scl_lcnt,
            Some(RpI2cRegister::FastSpeedHighCount) => state.fs_scl_hcnt,
            Some(RpI2cRegister::FastSpeedLowCount) => state.fs_scl_lcnt,
            Some(RpI2cRegister::DataCommand) => {
                let value = state.rx_fifo.pop_front().map_or_else(
                    || {
                        state.raw_intr |= Self::IC_INTR_RX_UNDER;
                        0
                    },
                    u32::from,
                );
                Self::update_fifo_interrupts(&mut state);
                value
            }
            Some(RpI2cRegister::InterruptStatus) => state.raw_intr & state.intr_mask,
            Some(RpI2cRegister::InterruptMask) => state.intr_mask,
            Some(RpI2cRegister::RawInterruptStatus) => state.raw_intr,
            Some(RpI2cRegister::ReceiveThreshold) => state.rx_tl,
            Some(RpI2cRegister::TransmitThreshold) => state.tx_tl,
            Some(RpI2cRegister::ClearInterrupt) => {
                let value = u32::from(state.raw_intr != 0);
                Self::clear_combined_interrupts(&mut state);
                value
            }
            Some(RpI2cRegister::ClearReceiveUnderflow) => {
                Self::read_clear_value(&mut state, Self::IC_INTR_RX_UNDER)
            }
            Some(RpI2cRegister::ClearReceiveOverflow) => {
                Self::read_clear_value(&mut state, Self::IC_INTR_RX_OVER)
            }
            Some(RpI2cRegister::ClearTransmitOverflow) => {
                Self::read_clear_value(&mut state, Self::IC_INTR_TX_OVER)
            }
            Some(RpI2cRegister::ClearReadRequest) => {
                Self::read_clear_value(&mut state, Self::IC_INTR_RD_REQ)
            }
            Some(RpI2cRegister::ClearTransmitAbort) => {
                let value = u32::from(state.raw_intr & Self::IC_INTR_TX_ABRT != 0);
                Self::clear_abort(&mut state);
                value
            }
            Some(RpI2cRegister::ClearReceiveDone) => {
                Self::read_clear_value(&mut state, Self::IC_INTR_RX_DONE)
            }
            Some(RpI2cRegister::ClearActivity) => {
                let value = u32::from(state.raw_intr & Self::IC_INTR_ACTIVITY != 0);
                if !state.active {
                    Self::clear_interrupt(&mut state, Self::IC_INTR_ACTIVITY);
                }
                value
            }
            Some(RpI2cRegister::ClearStopDetected) => {
                Self::read_clear_value(&mut state, Self::IC_INTR_STOP_DET)
            }
            Some(RpI2cRegister::ClearStartDetected) => {
                Self::read_clear_value(&mut state, Self::IC_INTR_START_DET)
            }
            Some(RpI2cRegister::ClearGeneralCall) => {
                Self::read_clear_value(&mut state, Self::IC_INTR_GEN_CALL)
            }
            Some(RpI2cRegister::Enable) => {
                u32::from(state.enable) | (u32::from(state.tx_cmd_block) << 2)
            }
            Some(RpI2cRegister::Status) => {
                let mut status = 0;
                if state.active {
                    status |= 1 << 0;
                }
                if state.tx_fifo.len() < IC_FIFO_DEPTH {
                    status |= 1 << 1;
                }
                if state.tx_fifo.is_empty() {
                    status |= 1 << 2;
                }
                if !state.rx_fifo.is_empty() {
                    status |= 1 << 3;
                }
                if state.rx_fifo.len() >= IC_FIFO_DEPTH {
                    status |= 1 << 4;
                }
                if state.active {
                    status |= 1 << 5;
                }
                status
            }
            Some(RpI2cRegister::TransmitFifoLevel) => {
                u32::try_from(state.tx_fifo.len()).expect("I²C FIFO length fits")
            }
            Some(RpI2cRegister::ReceiveFifoLevel) => {
                u32::try_from(state.rx_fifo.len()).expect("I²C FIFO length fits")
            }
            Some(RpI2cRegister::SdaHold) => state.sda_hold,
            Some(RpI2cRegister::TransmitAbortSource) => state.tx_abrt_source,
            Some(RpI2cRegister::SlaveDataNackOnly) => u32::from(state.slave_data_nack_only),
            Some(RpI2cRegister::DmaControl) => state.dma_control,
            Some(RpI2cRegister::DmaTransmitLevel) => state.dma_tx_level,
            Some(RpI2cRegister::DmaReceiveLevel) => state.dma_rx_level,
            Some(RpI2cRegister::SdaSetup) => state.sda_setup,
            Some(RpI2cRegister::AckGeneralCall) => u32::from(state.ack_general_call),
            Some(RpI2cRegister::EnableStatus) => u32::from(state.enable),
            Some(RpI2cRegister::FastSpeedSpikeLength) => state.fs_spklen,
            Some(RpI2cRegister::ClearRestartDetected) => {
                Self::read_clear_value(&mut state, Self::IC_INTR_RESTART_DET)
            }
            Some(RpI2cRegister::ComponentParameter) => 0,
            Some(RpI2cRegister::ComponentVersion) => 0x3230_312a,
            Some(RpI2cRegister::ComponentType) => 0x4457_0140,
            None => 0,
        };
        let value = match width {
            AccessWidth::Byte => (value >> (lane * 8)) & 0xff,
            AccessWidth::HalfWord => (value >> ((lane & 2) * 8)) & 0xffff,
            AccessWidth::Word => value,
            AccessWidth::DoubleWord => unreachable!("checked above"),
        };
        Ok(u64::from(value))
    }

    fn write(
        &mut self,
        offset: u64,
        width: AccessWidth,
        value: u64,
        at: SimTime,
    ) -> Result<(), DeviceError> {
        if width == AccessWidth::DoubleWord {
            return Err(DeviceError::new(
                "RP2350 I²C does not support 64-bit access",
            ));
        }
        let register_offset = (offset & 0x0fff) & !3;
        let register = RpI2cRegister::from_offset(register_offset);
        let alias = (offset >> 12) & 3;
        let value = match width {
            AccessWidth::Byte => {
                let value = u32::try_from(value & 0xff).expect("I²C byte fits");
                value | (value << 8) | (value << 16) | (value << 24)
            }
            AccessWidth::HalfWord => {
                let value = u32::try_from(value & 0xffff).expect("I²C halfword fits");
                value | (value << 16)
            }
            AccessWidth::Word => {
                u32::try_from(value & u64::from(u32::MAX)).expect("I²C register fits u32")
            }
            AccessWidth::DoubleWord => unreachable!("checked above"),
        };
        let mut state = self.state.borrow_mut();
        match register {
            Some(RpI2cRegister::Control) if !state.enable => {
                let value = Self::atomic_write(alias, state.con, value);
                let speed = match (value >> 1) & 0x3 {
                    1 => 1,
                    2 => 2,
                    // RP2350 supports standard and fast/Fast+ modes.  The
                    // hardware saturates an illegal value to its maximum.
                    _ => 2,
                };
                state.con = (value & IC_CON_WRITABLE_BITS & !0x6) | (speed << 1);
            }
            Some(RpI2cRegister::TargetAddress) if !state.enable => {
                state.tar = Self::atomic_write(alias, state.tar, value) & 0x0fff
            }
            Some(RpI2cRegister::SlaveAddress) if !state.enable => {
                state.sar = Self::atomic_write(alias, state.sar, value) & 0x03ff
            }
            Some(RpI2cRegister::StandardSpeedHighCount) if !state.enable => {
                state.ss_scl_hcnt =
                    (Self::atomic_write(alias, state.ss_scl_hcnt, value) & 0xffff).max(6)
            }
            Some(RpI2cRegister::StandardSpeedLowCount) if !state.enable => {
                state.ss_scl_lcnt =
                    (Self::atomic_write(alias, state.ss_scl_lcnt, value) & 0xffff).max(8)
            }
            Some(RpI2cRegister::FastSpeedHighCount) if !state.enable => {
                state.fs_scl_hcnt =
                    (Self::atomic_write(alias, state.fs_scl_hcnt, value) & 0xffff).max(6)
            }
            Some(RpI2cRegister::FastSpeedLowCount) if !state.enable => {
                state.fs_scl_lcnt =
                    (Self::atomic_write(alias, state.fs_scl_lcnt, value) & 0xffff).max(8)
            }
            Some(RpI2cRegister::DataCommand) if state.enable && alias == 0 => {
                if state.tx_fifo.len() >= IC_FIFO_DEPTH {
                    state.raw_intr |= Self::IC_INTR_TX_OVER;
                } else {
                    state.tx_fifo.push_back(value & 0x07ff);
                    Self::update_fifo_interrupts(&mut state);
                    self.drain_tx_fifo(&mut state, at)?;
                }
            }
            Some(RpI2cRegister::InterruptMask) => {
                state.intr_mask = Self::atomic_write(alias, state.intr_mask, value) & IC_INTR_BITS
            }
            Some(RpI2cRegister::ReceiveThreshold) => {
                state.rx_tl = (Self::atomic_write(alias, state.rx_tl, value) & 0xff)
                    .min((IC_FIFO_DEPTH - 1) as u32);
                Self::update_fifo_interrupts(&mut state);
            }
            Some(RpI2cRegister::TransmitThreshold) => {
                state.tx_tl = (Self::atomic_write(alias, state.tx_tl, value) & 0xff)
                    .min((IC_FIFO_DEPTH - 1) as u32);
                Self::update_fifo_interrupts(&mut state);
            }
            Some(RpI2cRegister::Enable) => {
                let current = u32::from(state.enable) | (u32::from(state.tx_cmd_block) << 2);
                let value = Self::atomic_write(alias, current, value) & 0x7;
                let enabled = value & 1 != 0;
                let block = value & 4 != 0;
                if enabled && value & 2 != 0 && state.enable {
                    Self::flush_fifos(&mut state);
                    state.active = false;
                    state.tx_abrt_source |= 1 << 16;
                    state.raw_intr |= Self::IC_INTR_TX_ABRT;
                }
                if !enabled {
                    state.active = false;
                    state.raw_intr = 0;
                    state.tx_abrt_source = 0;
                    Self::flush_fifos(&mut state);
                }
                state.enable = enabled;
                state.tx_cmd_block = enabled && block;
                Self::update_fifo_interrupts(&mut state);
                if enabled && !state.tx_cmd_block {
                    self.drain_tx_fifo(&mut state, at)?;
                }
            }
            Some(RpI2cRegister::SdaHold) if !state.enable => {
                state.sda_hold = Self::atomic_write(alias, state.sda_hold, value) & 0x00ff_ffff
            }
            Some(RpI2cRegister::SlaveDataNackOnly) if !state.enable => {
                state.slave_data_nack_only =
                    Self::atomic_write(alias, u32::from(state.slave_data_nack_only), value) & 1 != 0
            }
            Some(RpI2cRegister::DmaControl) => {
                state.dma_control = Self::atomic_write(alias, state.dma_control, value) & 0x3
            }
            Some(RpI2cRegister::DmaTransmitLevel) => {
                state.dma_tx_level = Self::atomic_write(alias, state.dma_tx_level, value) & 0xf
            }
            Some(RpI2cRegister::DmaReceiveLevel) => {
                state.dma_rx_level = Self::atomic_write(alias, state.dma_rx_level, value) & 0xf
            }
            Some(RpI2cRegister::SdaSetup) if !state.enable => {
                state.sda_setup = (Self::atomic_write(alias, state.sda_setup, value) & 0xff).max(2)
            }
            Some(RpI2cRegister::AckGeneralCall) if !state.enable => {
                state.ack_general_call =
                    Self::atomic_write(alias, u32::from(state.ack_general_call), value) & 1 != 0
            }
            Some(RpI2cRegister::FastSpeedSpikeLength) if !state.enable => {
                state.fs_spklen = Self::atomic_write(alias, state.fs_spklen, value) & 0xff
            }
            _ => {}
        }
        Ok(())
    }

    fn reset(&mut self, _kind: ResetKind) {
        self.state.borrow_mut().reset();
    }
}
